    prog: document.getElementById('progressBar').style.width,
    info: document.getElementById('infoTitle').textContent,
    eyebrow: document.getElementById('infoEyebrow').textContent,
    body: document.body.className,
    activeLabels: document.querySelectorAll('.stop-label.active').length
  })`)));
  await evalJs(`document.querySelectorAll('.stop-item')[3].click()`);
  await sleep(600);
  console.log('after jump:', JSON.stringify(await evalJs(`({
    btn: document.getElementById('btnTour').textContent,
    prog: document.getElementById('progressBar').style.width,
    info: document.getElementById('infoTitle').textContent,
    activeItems: document.querySelectorAll('.stop-item.active').length,
    activeLabels: document.querySelectorAll('.stop-label.active').length
  })`)));
  const shot = await send('Page.captureScreenshot', { format: 'png' });
  if (shot.result && shot.result.data) fs.writeFileSync('/tmp/alhambra-tour.png', Buffer.from(shot.result.data, 'base64'));
  console.log('screenshot bytes:', shot.result && shot.result.data ? Buffer.from(shot.result.data, 'base64').length : 0);
  await evalJs(`document.getElementById('btnOverview').click()`);
  await sleep(400);
  console.log('after overview:', JSON.stringify(await evalJs(`({
    btn: document.getElementById('btnTour').textContent,
    prog: document.getElementById('progressBar').style.width,
    info: document.getElementById('infoTitle').textContent,
    body: document.body.className
  })`)));
  ws.close();
})().catch(e => { console.error('ERR', e); process.exit(1); });
EOF
